//Initialize the output vars as only one will be used.
NumericResult = 0;
TextResult = String.Empty;
ErrorMessage=String.Empty;

string tempResult = string.Empty;
IEnumerable<JToken> tokens;

JObject jo;
JArray ja;

jo = JObject.Parse(Json);

try
{
	tokens = jo.SelectTokens(JsonPath);
	ja = new JArray(tokens);

	TextResult = ja.ToString();
}
catch (JsonException)
{
	ErrorMessage = "Unable to find value in supplied JSON.";
}
